CREATE OR REPLACE FUNCTION public.ensure_referral_code(_user_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_code text; BEGIN IF auth.role() <> 'service_role' AND (auth.uid() IS NULL OR auth.uid() <> _user_id) THEN RAISE EXCEPTION 'Access denied'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_user_id::text, 0)); SELECT code INTO v_code FROM public.referral_links WHERE user_id=_user_id ORDER BY created_at,id LIMIT 1; IF v_code IS NOT NULL THEN RETURN v_code; END IF; LOOP v_code := 'PRZ-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)); BEGIN INSERT INTO public.referral_links(user_id,code) VALUES(_user_id,v_code); RETURN v_code; EXCEPTION WHEN unique_violation THEN SELECT code INTO v_code FROM public.referral_links WHERE user_id=_user_id ORDER BY created_at,id LIMIT 1; IF v_code IS NOT NULL THEN RETURN v_code; END IF; END; END LOOP; END; $$; REVOKE ALL ON FUNCTION public.ensure_referral_code(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ensure_referral_code(uuid) TO authenticated,service_role;
ALTER TABLE public.payment_notify_log ADD COLUMN IF NOT EXISTS provider_message_id text, ADD COLUMN IF NOT EXISTS delivered_at timestamptz, ADD COLUMN IF NOT EXISTS delivery_status text, ADD COLUMN IF NOT EXISTS receipt_checked_at timestamptz;
ALTER TABLE public.payment_notify_attempts ADD COLUMN IF NOT EXISTS provider_message_id text;
COMMENT ON COLUMN public.payment_notify_log.sent_at IS 'Provider accepted timestamp; not evidence of handset delivery';
GRANT SELECT ON public.payment_notify_log,public.payment_notify_attempts TO authenticated; GRANT ALL ON public.payment_notify_log,public.payment_notify_attempts TO service_role;